```php
<?php
/**
 * Plugin Name: External Product Sync Extension
 * Description: Sincroniza productos externos vía REST API, registra CPT 'producto', gestiona cron automático y limpieza de transients.
 * Version: 1.0.0
 * Author: AI Assistant
 * License: GPL-2.0+
 */

if ( ! defined( 'ABSPATH' ) ) {
    exit; // Exit if accessed directly
}

/**
 * Clase principal para la sincronización de productos externos.
 * Gestiona hooks, cron, endpoint REST, parseo JSON, CPT y logging.
 */
class External_Product_Sync {

    /** URL del endpoint externo de productos */
    private $api_endpoint;

    /** Intervalo de sincronización en horas */
    private $sync_interval_hours = 2;

    /**
     * Constructor: Registra hooks globales y configura valores por defecto.
     */
    public function __construct() {
        add_action( 'plugins_loaded', [ $this, 'init' ] );
        add_action( 'wp', [ $this, 'cleanup_expired_transients' ] );
        add_filter( 'cron_schedules', [ $this, 'add_custom_cron_interval' ] );
        add_action( 'external_product_sync_cron', [ $this, 'run_sync_process' ] );

        // Configuración configurable vía wp_options o constante
        $this->api_endpoint = get_option( 'eps_api_endpoint', 'https://api.ejemplo.com/v1/productos' );
    }

    /**
     * Inicialización principal del plugin.
     * Se encarga del registro del Custom Post Type y la configuración inicial del cron.
     * 
     * @return void
     */
    public function init() {
        $this->register_product_cpt();
        $this->setup_cron_schedule();
    }

    /**
     * Registra el Custom Post Type 'producto' en WordPress.
     * Configura soporte para título, editor, campos personalizados y REST API nativa.
     * 
     * @return void
     */
    private function register_product_cpt() {
        if ( post_type_exists( 'producto' ) ) {
            return;
        }

        $labels = [
            'name'               => _x( 'Productos', 'post type general name', 'eps-textdomain' ),
            'singular_name'      => _x( 'Producto', 'post type singular name', 'eps-textdomain' ),
            'menu_name'          => _x( 'Productos Externos', 'admin menu', 'eps-textdomain' ),
            'name_admin_bar'     => _x( 'Producto', 'add new on admin bar', 'eps-textdomain' ),
            'add_new'            => _x( 'Agregar Nuevo', 'producto', 'eps-textdomain' ),
            'add_new_item'       => __( 'Agregar nuevo producto', 'eps-textdomain' ),
            'new_item'           => __( 'Nuevo producto', 'eps-textdomain' ),
            'edit_item'          => __( 'Editar producto', 'eps-textdomain' ),
            'view_item'          => __( 'Ver producto', 'eps-textdomain' ),
            'all_items'          => __( 'Todos los productos', 'eps-textdomain' ),
            'search_items'       => __( 'Buscar productos', 'eps-textdomain' ),
            'not_found'          => __( 'No se encontraron productos.', 'eps-textdomain' ),
        ];

        $args = [
            'labels'             => $labels,
            'public'             => true,
            'has_archive'        => false,
            'show_in_rest'       => true,
            'rewrite'            => [ 'slug' => 'productos' ],
            'supports'           => [ 'title', 'editor', 'custom-fields', 'thumbnail' ],
            'menu_icon'          => 'dashicons-cart',
            'capability_type'    => 'post',
        ];

        register_post_type( 'producto', $args );
    }

    /**
     * Configura un intervalo cron personalizado y programa el evento de sincronización.
     * Verifica que no exista una tarea idéntica antes de registrarla para evitar duplicados.
     * 
     * @return void
     */
    private function setup_cron_schedule() {
        if ( ! wp_next_scheduled( 'external_product_sync_cron' ) ) {
            wp_schedule_event( time(), 'every_' . $this->sync_interval_hours . '_hours', 'external_product_sync_cron' );
        }
    }

    /**
     * Añade un nuevo intervalo cron personalizado al array de WordPress.
     * 
     * @param array $schedules Array de intervalos cron existentes.
     * @return array Intervalos cron modificados con el nuevo intervalo.
     */
    public function add_custom_cron_interval( $schedules ) {
        $schedules[ 'every_' . $this->sync_interval_hours . '_hours' ] = [
            'display' => sprintf( __( 'Cada %d horas', 'eps-textdomain' ), $this->sync_interval_hours ),
            'interval'=> HOUR_IN_SECONDS * $this->sync_interval_hours,
        ];

        return $schedules;
    }

    /**
     * Ejecuta el proceso completo de sincronización desde el hook cron.
     * Orquesta la obtención de datos, parseo y guardado en base de datos.
     * 
     * @return void
     */
    public function run_sync_process() {
        $response = $this->fetch_external_products();

        if ( is_wp_error( $response ) || empty( $response['products'] ) ) {
            $this->log_via_wp_error( 'Sincronización fallida: No se recibieron productos válidos.', 500 );
            return;
        }

        $created  = 0;
        $updated  = 0;

        foreach ( $response['products'] as $product_data ) {
            if ( empty( $product_data['external_id'] ) ) {
                continue; // Saltar entradas sin identificador único
            }

            $result = $this->create_or_update_product( $product_data );

            if ( is_wp_error( $result ) ) {
                $this->log_via_wp_error( 'Error al procesar producto ID: ' . $product_data['external_id'], 422 );
                continue;
            }

            if ( $result['status'] === 'created' ) {
                $created++;
            } elseif ( $result['status'] === 'updated' ) {
                $updated++;
            }
        }

        // Logging informativo de resultados
        error_log( sprintf( '[EPS] Sync completada. Creados: %d, Actualizados: %d', $created, $updated ) );
    }

    /**
     * Realiza la solicitud HTTP al endpoint externo con lógica de timeout y reintentos.
     * 
     * @return array|WP_Error Array con productos parseados o WP_Error en caso de fallo.
     */
    private function fetch_external_products() {
        $max_retries   = 3;
        $timeout       = 30;
        $attempt       = 0;
        $http_response = null;

        while ( $attempt < $max_retries ) {
            $args = [
                'method'      => 'GET',
                'timeout'     => $timeout,
                'blocking'    => true,
                'sslverify'   => true,
                'headers'     => [ 'Accept' => 'application/json' ],
                'body'        => [],
            ];

            $http_response = wp_remote_get( esc_url_raw( $this->api_endpoint ), $args );

            if ( ! is_wp_error( $http_response ) && 200 === wp_remote_retrieve_response_code( $http_response ) ) {
                break; // Éxito, salir del bucle
            }

            $attempt++;
            if ( $attempt < $max_retries ) {
                sleep( 1 << $attempt ); // Backoff exponencial: 1s, 2s, 4s...
            }
        }

        if ( is_wp_error( $http_response ) || 200 !== wp_remote_retrieve_response_code( $http_response ) ) {
            return new WP_Error( 
                'eps_api_fetch_failed', 
                sprintf( 'Error al conectar con API externa. Intentos: %d', $attempt ), 
                [ 'status' => 503 ] 
            );
        }

        $body = wp_remote_retrieve_body( $http_response );
        return $this->parse_json_response( $body );
    }

    /**
     * Parsea la respuesta JSON del endpoint y valida su estructura.
     * 
     * @param string $raw_body Cuerpo de la respuesta HTTP en formato texto.
     * @return array|WP_Error Array estructurado de productos o WP_Error si el parseo falla.
     */
    private function parse_json_response( $raw_body ) {
        $decoded = json_decode( $raw_body, true );

        if ( json_last_error() !== JSON_ERROR_NONE ) {
            return new WP_Error( 
                'eps_json_parse_error', 
                'La respuesta de la API no es un JSON válido: ' . json_last_error_msg(), 
                [ 'status' => 400 ] 
            );
        }

        // Validación básica de estructura esperada
        if ( ! isset( $decoded['products'] ) || ! is_array( $decoded['products'] ) ) {
            return new WP_Error( 
                'eps_invalid_structure', 
                'La estructura JSON no contiene el índice esperado "products".', 
                [ 'status' => 422 ] 
            );
        }

        return [ 'products' => $decoded['products'] ];
    }

    /**
     * Crea o actualiza un producto como post tipo 'producto' y sus meta fields.
     * 
     * @param array $product_data Datos del producto desde la API externa.
     * @return array|WP_Error Array con estado de operación ('created'|'updated') o WP_Error.
     */
    private function create_or_update_product( $product_data ) {
        $external_id = sanitize_text_field( $product_data['external_id'] );

        // Buscar si ya existe por ID externo
        $existing_post = get_posts( [
            'post_type'   => 'producto',
            'meta_key'    => '_external_id',
            'meta_value'  => $external_id,
            'numberposts' => 1,
            'fields'      => 'ids',
            'no_found_rows' => true,
        ] );

        $post_id = ! empty( $existing_post ) ? $existing_post[0] : 0;

        $post_args = [
            'post_title'   => sanitize_text_field( $product_data['name'] ?? 'Producto sin nombre' ),
            'post_content' => wp_kses_post( $product_data['description'] ?? '' ),
            'post_status'  => 'publish',
            'post_type'    => 'producto',
        ];

        if ( $post_id ) {
            $post_args['ID'] = $post_id;
            wp_update_post( $post_args, true );
        } else {
            $new_id = wp_insert_post( $post_args, true );
            if ( is_wp_error( $new_id ) ) {
                return new WP_Error( 'eps_post_creation_failed', $new_id->get_error_message(), [ 'status' => 500 ] );
            }
            $post_id = $new_id;
        }

        // Actualizar meta fields solicitados
        update_post_meta( $post_id, '_external_id', $external_id );
        update_post_meta( $post_id, '_precio', floatval( $product_data['price'] ?? 0.00 ) );
        update_post_meta( $post_id, '_stock', intval( $product_data['stock'] ?? 0 ) );

        $image_url = esc_url_raw( $product_data['image_url'] ?? '' );
        if ( ! empty( $image_url ) ) {
            update_post_meta( $post_id, '_imagen_url', $image_url );
            // Opcional: Importar imagen remota como featured image
            // media_sideload_image( $image_url, $post_id, '', 'src' );
        }

        return [ 'status' => ! empty( $existing_post ) ? 'updated' : 'created', 'id' => $post_id ];
    }

    /**
     * Limpia los transients caducados mediante el hook 'wp'.
     * Recorre las opciones de WordPress, verifica timeouts y elimina caducados.
     * 
     * @return void
     */
    public function cleanup_expired_transients() {
        // Solo ejecutar en contexto de admin o cada X páginas para evitar overhead en frontend
        if ( is_admin() || defined('DOING_CRON') || get_transient( 'eps_last_cleanup' ) ) {
            return;
        }

        global $wpdb;
        $transient_prefix = "{$wpdb->prefix}transient_timeout_";

        // Obtener timeouts de transients activos
        $timeouts = $wpdb->get_col( "SELECT option_name FROM {$wpdb->options} WHERE option_name LIKE '{$transient_prefix}%'" );

        if ( empty( $timeouts ) ) {
            set_transient( 'eps_last_cleanup', 1, HOUR_IN_SECONDS ); // Cache local para no escanear siempre
            return;
        }

        $current_time = time();
        $deleted      = 0;

        foreach ( $timeouts as $timeout_key ) {
            $transient_key = str_replace( 'transient_timeout_', 'transient_', $timeout_key );

            if ( $current_time > get_option( $timeout_key, 0 ) ) {
                delete_option( $timeout_key );
                delete_option( $transient_key );
                $deleted++;
            }
        }

        if ( $deleted > 0 ) {
            set_transient( 'eps_last_cleanup', 1, MINUTE_IN_SECONDS * 5 ); // Evitar re-ejecución inmediata
            error_log( sprintf( '[EPS] Transients limpiados: %d eliminados.', $deleted ) );
        }
    }

    /**
     * Genera y registra errores utilizando WP_Error y el sistema de log de WordPress.
     * 
     * @param string $message Mensaje descriptivo del error.
     * @param int    $code    Código de error numérico o string.
     * @return WP_Error Instancia de WP_Error con el registro persistente.
     */
    public function log_via_wp_error( $message, $code = 400 ) {
        $wp_error = new WP_Error( 'eps_sync_error', $message, [ 'status' => intval( $code ) ] );

        // Registrar en error_log.php y depuración de WP si está habilitada
        error_log( sprintf( '[EPS Error %s]: %s', $code, $message ) );

        if ( defined( 'WP_DEBUG' ) && WP_DEBUG ) {
            error_log( wp_json_encode( $wp_error->get_error_data(), JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE ) );
        }

        return $wp_error;
    }
}

